mapper.update:
UPDATE knowledge_version_cleanup c
INNER JOIN knowledge_document d ON d.id = c.document_id
SET c.status = 'PROCESSING',
    c.execution_token = #{task.executionToken},
    c.lease_expires_at = #{task.leaseExpiresAt},
    c.retry_count = c.retry_count + CASE WHEN #{task.status} = 'FAILED' THEN 1 ELSE 0 END,
    c.next_retry_at = NULL,
    c.updated_at = #{now}
WHERE c.id = #{task.id}
    AND c.document_id = #{task.documentId}
    AND c.version = #{task.version}
    AND c.eligible_at  <=  #{now}
    AND c.status = #{task.status}
    AND ( c.status = 'PENDING' OR ( c.status = 'FAILED'
        AND c.next_retry_at IS NOT NULL
        AND c.next_retry_at  <=  #{now}))
AND d.active_version IS NOT NULL
AND TRIM(d.active_version) != ''
AND d.active_version != c.version

UPDATE knowledge_version_cleanup c
INNER JOIN knowledge_document d ON d.id = c.document_id
SET c.status = 'EXECUTING',
    c.updated_at = #{now}
WHERE c.id = #{task.id}
    AND c.document_id = #{task.documentId}
    AND c.version = #{task.version}
    AND c.status = 'PROCESSING'
    AND c.execution_token = #{task.executionToken}
    AND c.lease_expires_at > #{now}
    AND c.eligible_at  <=  #{now}
    AND d.active_version IS NOT NULL
    AND TRIM(d.active_version) != ''
    AND d.active_version != c.version

UPDATE knowledge_version_cleanup
SET status = 'COMPLETED',
    completed_at = #{now},
    next_retry_at = NULL,
    last_error = NULL,
    lease_expires_at = NULL,
    updated_at = #{now}
WHERE id = #{taskId}
    AND status = 'EXECUTING'
    AND execution_token = #{executionToken}

UPDATE knowledge_version_cleanup
SET status = 'FAILED',
    last_error = #{error},
    next_retry_at = #{nextRetryAt},
    lease_expires_at = NULL,
    updated_at = #{now}
WHERE id = #{taskId}
    AND status = 'EXECUTING'
    AND execution_token = #{executionToken}
